ns.AddQuests("lbrs", {
    { id = 4701, name = "Put Her Down", level = 59, minLevel = 55, faction = "Alliance", dungeon = "lbrs", giver = "Helendis Riverhorn", start = { npc = "Helendis Riverhorn", area = 46, x = 85.8, y = 69.0 }, finish = { npc = "Helendis Riverhorn", area = 46, x = 85.8, y = 69.0 }, steps = { { name = "Halycon", area = 1583 } }, objective = "Travel to Blackrock Spire and destroy the source of the worg menace. As you left Helendis, he shouted a name: Halycon. It is what the orcs refer to in regards to the worg." },
    { id = 4724, name = "The Pack Mistress", level = 59, minLevel = 55, faction = "Horde", dungeon = "lbrs", giver = "Galamav the Marksman", start = { npc = "Galamav the Marksman", area = 3, x = 6.0, y = 47.7 }, finish = { npc = "Galamav the Marksman", area = 3, x = 6.0, y = 47.7 }, steps = { { name = "Halycon", area = 1583 } }, objective = "Slay Halycon, pack mistress of the Bloodaxe worg." },
    { id = 4726, name = "Broodling Essence", level = 52, minLevel = 50, giver = "Tinkee Steamboil", start = { npc = "Tinkee Steamboil", area = 46, x = 65.2, y = 24.0 }, finish = { npc = "Tinkee Steamboil", area = 46, x = 65.2, y = 24.0 }, steps = { { name = "Broodling Essence", area = 46, x = 86.4, y = 31.5 } }, objective = "Bring 8 Broodling Essence and the Draco-Incarcinatrix 900 to Tinkee Steamboil at the Flame Crest in the Burning Steppes." }, -- chain
    { id = 4729, name = "Kibler's Exotic Pets", level = 59, minLevel = 55, dungeon = "lbrs", giver = "Kibler", start = { npc = "Kibler", area = 46, x = 65.9, y = 21.9 }, finish = { npc = "Kibler", area = 46, x = 65.9, y = 21.9 }, objective = "Travel to Blackrock Spire and find Bloodaxe Worg Pups. Use the cage to carry the ferocious little beasts. Bring back a Caged Worg Pup to Kibler." },
    { id = 4734, name = "Egg Freezing", level = 60, minLevel = 57, requires = { 4810 }, dungeon = "lbrs", giver = "Tinkee Steamboil", start = { npc = "Tinkee Steamboil", area = 46, x = 65.2, y = 24.0 }, finish = { npc = "Tinkee Steamboil", area = 46, x = 65.2, y = 24.0 }, steps = { { name = "Rookery Egg", area = 1583 } }, objective = "Use the Eggscilloscope Prototype on an egg in the Rookery." },
    { id = 4735, name = "Egg Collection", level = 60, minLevel = 57, requires = { 4734 }, dungeon = "lbrs", giver = "Tinkee Steamboil", start = { npc = "Tinkee Steamboil", area = 46, x = 65.2, y = 24.0 }, finish = { npc = "Tinkee Steamboil", area = 46, x = 65.2, y = 24.0 }, steps = { { name = "Rookery Egg", area = 1583 } }, objective = "Bring 8 Collected Dragon Eggs and the Collectronic Module to Tinkee Steamboil at Flame Crest in the Burning Steppes." },
    { id = 4742, name = "Seal of Ascension (1/2)", level = 60, minLevel = 57, dungeon = "lbrs", giver = "Scarshield Infiltrator", start = { npc = "Scarshield Infiltrator" }, finish = { npc = "Scarshield Infiltrator" }, steps = { { name = "Gemstone of Spirestone", area = 1583, mobs = { "Highlord Omokk" } }, { name = "Gemstone of Smolderthorn", area = 1583, mobs = { "War Master Voone" } }, { name = "Gemstone of Bloodaxe", area = 1583, mobs = { "Overlord Wyrmthalak" } }, { name = "Unadorned Seal of Ascension", area = 1583, mobs = { "Bannok Grimaxe", "Bloodaxe Evoker", "Bloodaxe Raider", "Bloodaxe Veteran" } } }, objective = "Find the three gemstones of command: The Gemstone of Smolderthorn, Gemstone of Spirestone, and Gemstone of Bloodaxe. Return them, along with the Unadorned Seal of Ascension, to Vaelan.  The Generals, as told to you by Vaelan, are: War Master Voone of the Smolderthorn; Highlord Omokk of the Spirestone; and Overlord Wyrmthalak of the Bloodaxe." },
    { id = 4743, name = "Seal of Ascension (2/2)", level = 60, minLevel = 60, requires = { 4742 }, dungeon = "lbrs", giver = "Scarshield Infiltrator", start = { npc = "Scarshield Infiltrator" }, finish = { npc = "Scarshield Infiltrator" }, steps = { { name = "Forged Seal of Ascension", area = 15, x = 56.4, y = 87.8 } }, objective = "Travel to the Wyrmbog in Dustwallow Marsh. Find the ancient drake, Emberstrife and beat him without mercy until his will is broken.  It is at that moment which you must place the Unforged Seal of Ascension before the great beast. You must then be quick to use the Orb of Draconic Energy on his weakened form and claim dominion over his mental faculties. Control the beast and force the Flames of the Black Dragonflight upon the Unforged Seal of Ascension!" },
    { id = 4764, name = "Doomrigger's Clasp", level = 60, minLevel = 57, faction = "Alliance", dungeon = "lbrs", giver = "Mayara Brightwing", start = { npc = "Mayara Brightwing", area = 46, x = 84.8, y = 69.1 }, finish = { npc = "Mayara Brightwing", area = 46, x = 84.8, y = 69.1 }, steps = { { name = "Doomrigger's Clasp", area = 1583 } }, objective = "Bring Doomrigger's Clasp to Mayara Brightwing in the Burning Steppes." },
    { id = 4765, name = "Delivery to Ridgewell", level = 60, minLevel = 57, requires = { 4764 }, faction = "Alliance", giver = "Mayara Brightwing", start = { npc = "Mayara Brightwing", area = 46, x = 84.8, y = 69.1 }, finish = { npc = "Count Remington Ridgewell", area = 1519, x = 74.0, y = 30.2 }, objective = "Bring Ridgewell's Crate to Remington Ridgewell in Stormwind." },
