    { id = 1318, name = "Unfinished Gordok Business (1/2)", level = 60, minLevel = 56, dungeon = "dm", steps = { { name = "Gauntlet of Gordok Might", area = 10022 } }, objective = "Find the Gauntlet of Gordok Might and return it to Captain Kromcrush in Dire Maul.  According to Kromcrush, the \"old timey story\" says that Tortheldrin - a \"creepy\" elf who called himself a prince - stole it from one of the Gordok kings." },
