    { id = 7441, name = "Pusillin and the Elder Azj'Tordin", level = 58, minLevel = 54, dungeon = "dm", giver = "Azj'Tordin", start = { npc = "Azj'Tordin", area = 357, x = 76.9, y = 37.4 }, finish = { npc = "Azj'Tordin", area = 357, x = 76.9, y = 37.4 }, steps = { { name = "Book of Incantations", area = 10026, mobs = { "Pusillin" } } }, objective = "Travel to Dire Maul and locate the Imp, Pusillin. Convince Pusillin to give you Azj'Tordin's Book of Incantations through any means necessary.  Return to Azj'Tordin at the Lariss Pavilion in Feralas should you recover the Book of Incantations." },
    { id = 7461, name = "The Madness Within", level = 60, minLevel = 57, dungeon = "dm", giver = "Shen'dralar Ancient", start = { npc = "Shen'dralar Ancient" }, finish = { npc = "Shen'dralar Ancient" }, steps = { { name = "Immol'thar", area = 10025 }, { name = "Prince Tortheldrin", area = 10022 } }, objective = "You must destroy the guardians surrounding the 5 Pylons that power the Prison of Immol'thar. Once the Pylons have powered down, the force field surrounding Immol'thar will have dissipated.  Enter the Prison of Immol'thar and eradicate the foul demon that stands at its heart. Finally, confront Prince Tortheldrin in Athenaeum.  Return to the Shen'dralar Ancient in the courtyard should you complete this quest." },
