    { id = 5341, name = "Barov Family Fortune", level = 60, minLevel = 52, faction = "Horde", dungeon = "scho", giver = "Alexi Barov", start = { npc = "Alexi Barov", area = 85, x = 83.1, y = 71.6 }, finish = { npc = "Alexi Barov", area = 85, x = 83.1, y = 71.6 }, steps = { { name = "The Deed to Brill", area = 2057 }, { name = "The Deed to Caer Darrow", area = 2057 }, { name = "The Deed to Southshore", area = 2057 }, { name = "The Deed to Tarren Mill", area = 2057 } }, objective = "Venture to the Scholomance and recover the Barov family fortune. Four deeds make up this fortune: The Deed to Caer Darrow; The Deed to Brill; The Deed to Tarren Mill; and The Deed to Southshore. Return to Alexi Barov when you have completed this task." },
    { id = 5342, name = "The Last Barov", level = 60, minLevel = 52, requires = { 5341 }, faction = "Horde", giver = "Alexi Barov", start = { npc = "Alexi Barov", area = 85, x = 83.1, y = 71.6 }, finish = { npc = "Alexi Barov", area = 85, x = 83.1, y = 71.6 }, steps = { { name = "Head of Weldon Barov", area = 28, x = 43.5, y = 83.7, mobs = { "Weldon Barov" } } }, objective = "Travel to Chillwind Camp - Alliance territory - and assassinate Weldon Barov. Take his head and return to Alexi Barov.  Be warned, Weldon will probably be well protected by Alliance scum." }, -- chain
    { id = 5343, name = "Barov Family Fortune", level = 60, minLevel = 52, faction = "Alliance", dungeon = "scho", giver = "Weldon Barov", start = { npc = "Weldon Barov", area = 28, x = 43.5, y = 83.7 }, finish = { npc = "Weldon Barov", area = 28, x = 43.5, y = 83.7 }, steps = { { name = "The Deed to Brill", area = 2057 }, { name = "The Deed to Caer Darrow", area = 2057 }, { name = "The Deed to Southshore", area = 2057 }, { name = "The Deed to Tarren Mill", area = 2057 } }, objective = "Venture to the Scholomance and recover the Barov family fortune. Four deeds make up this fortune: The Deed to Caer Darrow; The Deed to Brill; The Deed to Tarren Mill; and The Deed to Southshore. Return to Weldon Barov when you have completed this task." },
    { id = 5344, name = "The Last Barov", level = 60, minLevel = 52, requires = { 5343 }, faction = "Alliance", giver = "Weldon Barov", start = { npc = "Weldon Barov", area = 28, x = 43.5, y = 83.7 }, finish = { npc = "Weldon Barov", area = 28, x = 43.5, y = 83.7 }, steps = { { name = "Head of Alexi Barov", area = 85, x = 83.1, y = 71.6, mobs = { "Alexi Barov" } } }, objective = "Travel to the Bulwark - Horde territory - and assassinate Alexi Barov. Take his head and return to Weldon Barov.  Be warned, Alexi will probably be well protected by Horde filth." }, -- chain
    { id = 5382, name = "Doctor Theolen Krastinov, the Butcher", level = 60, minLevel = 55, dungeon = "scho", giver = "Eva Sarkhoff", start = { npc = "Eva Sarkhoff", area = 28, x = 70.2, y = 73.7 }, finish = { npc = "Eva Sarkhoff", area = 28, x = 70.2, y = 73.7 }, steps = { { name = "Doctor Theolen Krastinov", area = 2057 }, { name = "Remains of Eva Sarkhoff Burned", area = 2057 }, { name = "Remains of Lucien Sarkhoff Burned", area = 2057 } }, objective = "Find Doctor Theolen Krastinov inside the Scholomance. Destroy him, then burn the Remains of Eva Sarkhoff and the Remains of Lucien Sarkhoff. Return to Eva Sarkhoff when the task is complete." },
    { id = 5383, name = "[Not Used] Krastinov's Bag of Horrors", level = 60, minLevel = 2, objective = "Take the Bag of Horrors to Eva Sarkhoff on Caer Darrow." },
    { id = 5384, name = "Kirtonos the Herald", level = 60, minLevel = 55, requires = { 5515 }, dungeon = "scho", giver = "Eva Sarkhoff", start = { npc = "Eva Sarkhoff", area = 28, x = 70.2, y = 73.7 }, finish = { npc = "Eva Sarkhoff", area = 28, x = 70.2, y = 73.7 }, steps = { { name = "Kirtonos the Herald", area = 2057 } }, objective = "Return to the Scholomance with the Blood of Innocents. Find the porch and place the Blood of Innocents in the brazier. Kirtonos will come to feast upon your soul.  Fight valiantly, do not give an inch! Destroy Kirtonos and return to Eva Sarkhoff." },
    { id = 5461, name = "The Human, Ras Frostwhisper", level = 60, minLevel = 57, requires = { 5384 }, giver = "Magistrate Marduke", start = { npc = "Magistrate Marduke", area = 28, x = 70.6, y = 74.1 }, finish = { npc = "Magistrate Marduke", area = 28, x = 70.6, y = 74.1 }, steps = { { name = "Keepsake of Remembrance", area = 45, x = 23.3, y = 65.7 } }, objective = "Travel to the Arathi Highlands, to the ruins of Stromgarde. Search Stromgarde for a Keepsake of Remembrance. If you find such an item, return with it to Magistrate Marduke." }, -- chain
    { id = 5462, name = "The Dying, Ras Frostwhisper", level = 60, minLevel = 57, requires = { 5461 }, giver = "Magistrate Marduke", start = { npc = "Magistrate Marduke", area = 28, x = 70.6, y = 74.1 }, finish = { npc = "Leonid Barthalomew the Revered", area = 139, x = 81.7, y = 57.8 }, objective = "Travel to Light's Hope in Eastern Plaguelands and seek out Leonid Barthalomew the Revered. Show him the Keepsake of Remembrance and tell him all that you have discovered." }, -- chain
    { id = 5464, name = "Menethil's Gift", level = 60, minLevel = 57, requires = { 5463 }, giver = "Menethil's Gift", start = { npc = "Menethil's Gift", area = 2017 }, finish = { npc = "Leonid Barthalomew the Revered", area = 139, x = 81.7, y = 57.8 }, objective = "Take the Soulbound Keepsake to Leonid Barthalomew in Eastern Plaguelands." }, -- chain
    { id = 5465, name = "Soulbound Keepsake", level = 60, minLevel = 57, requires = { 5464 }, giver = "Leonid Barthalomew the Revered", start = { npc = "Leonid Barthalomew the Revered", area = 139, x = 81.7, y = 57.8 }, finish = { npc = "Magistrate Marduke", area = 28, x = 70.6, y = 74.1 }, objective = "Return to Magistrate Marduke in Caer Darrow. Show him the Soulbound Keepsake." }, -- chain
    { id = 5466, name = "The Lich, Ras Frostwhisper", level = 60, minLevel = 57, requires = { 5465 }, dungeon = "scho", giver = "Magistrate Marduke", start = { npc = "Magistrate Marduke", area = 28, x = 70.6, y = 74.1 }, finish = { npc = "Magistrate Marduke", area = 28, x = 70.6, y = 74.1 }, steps = { { name = "Human Head of Ras Frostwhisper", area = 2057, mobs = { "Ras Frostwhisper" } } }, objective = "Find Ras Frostwhisper in the Scholomance. When you have found him, use the Soulbound Keepsake on his undead visage. Should you succeed in reverting him to a mortal, strike him down and recover the Human Head of Ras Frostwhisper. Take the head back to Magistrate Marduke." },
    { id = 5515, name = "Krastinov's Bag of Horrors", level = 60, minLevel = 55, requires = { 5382 }, dungeon = "scho", giver = "Eva Sarkhoff", start = { npc = "Eva Sarkhoff", area = 28, x = 70.2, y = 73.7 }, finish = { npc = "Eva Sarkhoff", area = 28, x = 70.2, y = 73.7 }, steps = { { name = "Krastinov's Bag of Horrors", area = 2057, mobs = { "Jandice Barov" } } }, objective = "Locate Jandice Barov in the Scholomance and destroy her. From her corpse recover Krastinov's Bag of Horrors. Return the bag to Eva Sarkhoff." },
