    { id = 5848, name = "Of Love and Family (2/2)", level = 60, minLevel = 52, requires = { 5846 }, dungeon = "strat", giver = "Artist Renfray", start = { npc = "Artist Renfray", area = 28, x = 65.8, y = 75.4 }, finish = { npc = "Tirion Fordring", area = 139, x = 7.6, y = 43.6 }, steps = { { name = "Of Love and Family", area = 2017 } }, objective = "Travel to Stratholme, in the northern part of the Plaguelands. It is in the Scarlet Bastion that you will find the painting 'Of Love and Family,' hidden behind another painting depicting the twin moons of our world.  Return the painting to Tirion Fordring." },
