    { id = 5862, name = "Scarlet Subterfuge", level = 60, minLevel = 52, requires = { 5861 }, giver = "Myranda the Hag", start = { npc = "Myranda the Hag", area = 28, x = 50.8, y = 77.9 }, finish = { npc = "Highlord Taelan Fordring", area = 28, x = 42.0, y = 14.8 }, objective = "Speak to Myranda to gain the Scarlet Illusion. Travel to Hearthglen while under the Scarlet Illusion and deliver Tirion's Gift to Highlord Taelan Fordring.  Hearthglen is to the north, Taelan should be inside of Mardenholde Keep." }, -- chain
    { id = 5944, name = "In Dreams", level = 60, minLevel = 52, requires = { 5862 }, giver = "Highlord Taelan Fordring", start = { npc = "Highlord Taelan Fordring", area = 28, x = 42.0, y = 14.8 }, finish = { npc = "Lord Tirion Fordring", area = 28, x = 54.0, y = 24.5 }, steps = { { name = "Redemption?", area = 28, x = 53.9, y = 24.3 } }, objective = "Escort Taelan Fordring out of Hearthglen." }, -- chain
    { id = 6022, name = "To Kill With Purpose", level = 58, minLevel = 54, faction = "Horde", giver = "Nathanos Blightcaller", start = { npc = "Nathanos Blightcaller", area = 139, x = 26.5, y = 74.7 }, finish = { npc = "Nathanos Blightcaller", area = 139, x = 26.5, y = 74.7 }, objective = "Travel to Corin's Crossing to the east and slaughter the Scourge that inhabit the town. Collect 7 pieces of Living Rot in under 10 minutes. Use the Mortar and Pestle to grind the Living Rot into Coagulated Rot." }, -- chain
