    { id = 6133, name = "The Ranger Lord's Behest", level = 60, minLevel = 54, faction = "Horde", giver = "Nathanos Blightcaller", start = { npc = "Nathanos Blightcaller", area = 139, x = 26.5, y = 74.7 }, finish = { npc = "Nathanos Blightcaller", area = 139, x = 26.5, y = 74.7 }, steps = { { name = "Pathstrider", area = 139, x = 53.3, y = 18.1 }, { name = "Ranger", area = 139, x = 52.2, y = 18.5 }, { name = "Woodsman", area = 139, x = 52.4, y = 18.4 }, { name = "Quel'Thalas Registry", area = 139, x = 52.1, y = 18.3 } }, objective = "Travel to the northern borders of the Eastern Plaguelands and recover the Quel'Thalas Registry. The item is somewhere in the Quel'Lithien lodge.  You must also slay 8 Rangers, 8 Pathstriders, and 8 Woodsmen." }, -- chain
